import React from 'react';
import { Link } from 'react-router-dom';

function HomePage() {
  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      background: 'linear-gradient(120deg, #232526 0%, #414345 100%)',
      color: '#fff',
      fontFamily: 'Montserrat, sans-serif',
      animation: 'fadeIn 1.2s cubic-bezier(0.23, 1, 0.32, 1)',
      position: 'relative'
    }}>
      <div style={{
        maxWidth: 600,
        textAlign: 'center',
        padding: 32,
        borderRadius: 24,
        background: 'rgba(0,0,0,0.25)',
        boxShadow: '0 8px 32px rgba(0,0,0,0.18)'
      }}>
        <img
          src="https://cdn.pixabay.com/photo/2017/01/06/19/15/auto-1957037_1280.png"
          alt="Car Illustration"
          style={{ width: 180, marginBottom: 24, filter: 'drop-shadow(0 4px 24px #ffb34788)' }}
        />
        <h1 style={{ fontSize: '2.8rem', fontWeight: 800, letterSpacing: 2, marginBottom: 12 }}>
          Welcome to <span style={{ color: '#ffb347', textShadow: '0 2px 12px #ffb34755' }}>Cars Collection</span> Website
        </h1>
        <p style={{ fontSize: '1.25rem', color: '#bdbdbd', marginBottom: 32 }}>
          Explore the world's finest cars, from supercars to classics, electrics, and concepts. Start your journey now!
        </p>
        <Link to="/dashboard" style={{
          display: 'inline-block',
          marginTop: 8,
          padding: '16px 40px',
          background: 'linear-gradient(90deg, #ffb347 0%, #ffcc80 100%)',
          color: '#232526',
          borderRadius: 32,
          fontWeight: 700,
          textDecoration: 'none',
          fontSize: '1.3rem',
          letterSpacing: 1,
          boxShadow: '0 4px 24px #ffb34755',
          transition: 'transform 0.18s, box-shadow 0.18s',
        }}
        onMouseOver={e => { e.currentTarget.style.transform = 'scale(1.07)'; e.currentTarget.style.boxShadow = '0 8px 32px #ffb34788'; }}
        onMouseOut={e => { e.currentTarget.style.transform = 'scale(1)'; e.currentTarget.style.boxShadow = '0 4px 24px #ffb34755'; }}
        >
          Go to Dashboard
        </Link>
      </div>
      <div style={{
        position: 'fixed',
        right: 24,
        bottom: 16,
        color: '#bdbdbd',
        fontSize: '1rem',
        opacity: 0.85,
        letterSpacing: 1,
        zIndex: 10
      }}>
        Developed by <span style={{ color: '#ffb347', fontWeight: 600 }}>Ranbir Singh</span>
      </div>
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
      `}</style>
    </div>
  );
}

export default HomePage;
